(()=>{var p=(e,i)=>{e.ui.registry.addMenuButton("snippets",{text:"Snippets",fetch:n=>{fetch("index.php?rex-api-call=tinymce_get_snippets").then(t=>t.json()).then(t=>{if(t.length===0){n([{type:"menuitem",text:"Keine Snippets vorhanden",enabled:!1,onAction:()=>{}}]);return}let r=t.map(s=>({type:"menuitem",text:s.title,onAction:()=>{let a=e.serializer.serialize(e.parser.parse(s.content));e.insertContent(a)}}));n(r)}).catch(t=>{console.error("Error fetching snippets:",t),n([{type:"menuitem",text:"Fehler beim Laden",enabled:!1,onAction:()=>{}}])})}})};tinymce.PluginManager.add("snippets",(e,i)=>(p(e,i),{getMetadata:()=>({name:"FriendsOfREDAXO Snippets",url:"https://github.com/FriendsOfREDAXO/tinymce"})}));})();
